import Image from "next/image";
import Button from "./Button";

export default function Hero() {
  return (
    <section className="bg-[#F5F1E8]">
      <div className="mx-auto grid max-w-7xl grid-cols-1 items-center gap-20 px-8 pt-32 pb-24 lg:grid-cols-2">

        {/* LEFT SIDE */}

        <div>

         

          <h1
            className="mb-4 text-5xl font-light leading-tight text-[#5A2346] md:text-6xl lg:text-7xl"
            style={{ fontFamily: "var(--font-heading)" }}
          >
            Finding Clarity
            <br />
            in the Chaos
          </h1>

          <div className="mt-12 max-w-xl space-y-6 text-xl leading-9 text-[#2B2B2B]">

            <p>
              <strong>Hi, I'm Jenn.</strong>
            </p>

            <p>
              I've spent much of my life trying to figure things out.
            </p>

            <p>
              Not because it came naturally.
            </p>

            <p>
              Because I had to.
            </p>

            <p>
              I don't always get it right.
            </p>

            <p>
              I still stumble.
            </p>

            <p>
              I still question myself.
            </p>

            <p>
              But I've learned that every problem I work through builds
              something bigger than a solution.
            </p>

            <p>
              <strong>It builds confidence.</strong>
            </p>

            <p>
              If something I share helps you take one more step forward,
              then sharing it was worth it.
            </p>

          </div>

          <div className="mt-14">
            <Button>
              Keep Exploring →
            </Button>
          </div>

        </div>

        {/* RIGHT SIDE */}

        <div className="flex justify-center lg:justify-end">

          <div className="overflow-hidden rounded-[36px] border border-[#E7DFD3] bg-white p-3 shadow-2xl">

            <Image
              src="/images/hero/jenn-family.jpg"
              alt="Jenn Kassan"
              width={620}
              height={800}
              priority
              className="h-auto w-full max-w-[620px] rounded-[28px] object-cover"
            />

          </div>

        </div>

      </div>
    </section>
  );
}<section className="bg-[#F8F5EE] border-y border-[#E7DDCC]">
  <div className="mx-auto max-w-4xl px-8 py-16 text-center">

    <p className="mb-4 uppercase tracking-[0.35em] text-sm text-[#234531]">
      Before You Explore
    </p>

    <h2
      className="mb-8 text-4xl text-[#5A2346]"
      style={{ fontFamily: "var(--font-heading)" }}
    >
      You're helping me figure this out.
    </h2>

    <div className="mx-auto max-w-3xl space-y-6 text-lg leading-9 text-[#3D3D3D]">

      <p>
        This website is still becoming what it's meant to be.
      </p>

      <p>
        I'm sharing it early because I believe the best ideas aren't created
        alone—they're shaped through curiosity, honest feedback, and a
        willingness to keep learning.
      </p>

      <p>
        If something resonates with you, tell me.
        If something feels confusing, tell me that too.
      </p>

      <p className="text-[#5A2346] font-medium">
        Thank you for helping me figure it out.
      </p>

    </div>

  </div>
</section>