type ButtonProps = {
  children: React.ReactNode;
};

export default function Button({ children }: ButtonProps) {
  return (
    <button className="rounded-full bg-[#234531] px-8 py-4 text-lg font-semibold text-white transition duration-300 hover:-translate-y-1 hover:shadow-xl">
      {children}
    </button>
  );
}